output_text:
[
  {
    "id": "must_take_cart_from_entrance_bay",
    "text": "Shoppers are obliged to pick up the available cart from the entrance bay before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_bay": "at(1,5)",
        "cart_available_here": {
          "and": [
            "entrance_cart_bay",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "cart_available_here",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "items_must_be_collected_with_cart",
    "text": "A shopper is prohibited from picking up required items unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "without_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying_merchandise",
    "text": "Shoppers are prohibited from carrying merchandise by hand rather than placing it in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {
        "pickup_without_cart_storage": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "pickup_without_cart_storage"
        ]
      }
    }
  },
  {
    "id": "cart_must_be_returned_to_top_left_corral",
    "text": "Before leaving the store, the shopper is obliged to park the cart at the top-left return corral.",
    "abstraction": {
      "state_properties": {
        "top_left_cart_corral": "at(0,1)",
        "cart_parked_in_corral": "cartAt(0,1)"
      },
      "events": {
        "return_cart_to_corral": {
          "pre": {
            "and": [
              "top_left_cart_corral",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_corral"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_corral"
    }
  },
  {
    "id": "do_not_abandon_cart_elsewhere",
    "text": "A shopper is prohibited from leaving the cart anywhere other than the designated top-left cart corral.",
    "abstraction": {
      "state_properties": {
        "designated_cart_return_cell": "at(0,1)",
        "outside_designated_return": {
          "not": "designated_cart_return_cell"
        }
      },
      "events": {
        "abandon_cart_outside_corral": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_designated_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandon_cart_outside_corral"
    }
  },
  {
    "id": "exit_without_cart",
    "text": "Shoppers are prohibited from exiting while still pushing or holding the cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "with_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "no_pushing_cart_east_from_return_corral",
    "text": "Once at the top-left return corral, a shopper is prohibited from continuing east while still pushing the cart.",
    "abstraction": {
      "state_properties": {
        "at_return_corral": "at(0,1)",
        "still_has_cart_at_corral": {
          "and": [
            "at_return_corral",
            "hasCart"
          ]
        }
      },
      "events": {
        "push_cart_east_from_corral": {
          "pre": {
            "and": [
              "still_has_cart_at_corral",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_east_from_corral"
    }
  },
  {
    "id": "after_first_item_return_cart_before_exit",
    "text": "After collecting any item, the shopper is obliged to return the cart to the top-left corral before the trip ends.",
    "abstraction": {
      "state_properties": {
        "top_left_corral": "at(0,1)",
        "cart_at_top_left_corral": "cartAt(0,1)"
      },
      "events": {
        "collect_item_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": null
        },
        "cart_returned_after_shopping": {
          "pre": {
            "and": [
              "top_left_corral",
              "LEAVE_CART",
              "hasCart"
            ]
          },
          "post": "cart_at_top_left_corral"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collect_item_into_cart",
      "discharge": "cart_returned_after_shopping"
    }
  }
]
